insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('17332914-3d18-530c-91a1-52b8711ccb47', 'After death no ATP is produced [1]; so myosin heads cannot detach from actin and the cross-bridges remain, locking the muscle [1].', 'After death no ATP is produced [1]; so myosin heads cannot detach from actin and the cross-bridges remain, locking the muscle [1].', '[{"text": "Marking point 1", "any": ["atp", "no atp"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["detach", "remain attached", "stay bound", "cannot release"], "all": [], "marks": 1}]'::jsonb, 'After death no ATP is produced [1]; so myosin heads cannot detach from actin and the cross-bridges remain, locking the muscle [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
