insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('17ba2514-4281-56e2-99b2-987d743fbb78', 'Smooth cartilage covers the bone ends, reducing friction [1]; synovial fluid lubricates the joint [1]; ligaments hold the bones together so the joint is stable while moving [1].', 'Smooth cartilage covers the bone ends, reducing friction [1]; synovial fluid lubricates the joint [1]; ligaments hold the bones together so the joint is stable while moving [1].', '[{"text": "Marking point 1", "any": ["cartilage"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["synovial fluid", "lubricat"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["ligament", "capsule", "stable"], "all": [], "marks": 1}]'::jsonb, 'Smooth cartilage covers the bone ends, reducing friction [1]; synovial fluid lubricates the joint [1]; ligaments hold the bones together so the joint is stable while moving [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
