insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3aff9871-9f5a-5066-9754-6902f0ec967f', 'short', 'Explain how auxin causes a shoot to bend towards light.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3aff9871-9f5a-5066-9754-6902f0ec967f', 'Auxin is moved to the shaded side of the shoot [1] by auxin efflux carriers positioned on that side of the cells [1]; auxin promotes H⁺ secretion into the cell walls, loosening cross-links between cellulose [1]; cells on the shaded side elongate more, so the shoot bends towards the light [1].', 'Auxin is moved to the shaded side of the shoot [1] by auxin efflux carriers positioned on that side of the cells [1]; auxin promotes H⁺ secretion into the cell walls, loosening cross-links between cellulose [1]; cells on the shaded side elongate more, so the shoot bends towards the light [1].', '[{"text": "Marking point 1", "any": ["shaded", "dark side", "away from the light"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["efflux", "carrier", "transport"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["hydrogen ion", "acid", "apoplast"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["elongat", "faster", "grow more"], "all": [], "marks": 1}]'::jsonb, 'Auxin is moved to the shaded side of the shoot [1] by auxin efflux carriers positioned on that side of the cells [1]; auxin promotes H⁺ secretion into the cell walls, loosening cross-links between cellulose [1]; cells on the shaded side elongate more, so the shoot bends towards the light [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('7b9087dc-3846-543d-a0db-da3785567ca6', '3aff9871-9f5a-5066-9754-6902f0ec967f', 25);
