insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d74d78fd-49aa-588e-90fc-76317221e351', 'Grow seedlings in a box with light entering from one side only, with a control group in uniform light [1]; measure the angle of curvature after a set time with a protractor/image analysis [1]; keep species, age, temperature and water the same and use many seedlings to calculate a mean [1].', 'Grow seedlings in a box with light entering from one side only, with a control group in uniform light [1]; measure the angle of curvature after a set time with a protractor/image analysis [1]; keep species, age, temperature and water the same and use many seedlings to calculate a mean [1].', '[{"text": "Marking point 1", "any": ["one side", "unilateral", "lamp", "box with a hole"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["angle", "curvature", "protractor", "measure"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["control", "same", "repeat", "several"], "all": [], "marks": 1}]'::jsonb, 'Grow seedlings in a box with light entering from one side only, with a control group in uniform light [1]; measure the angle of curvature after a set time with a protractor/image analysis [1]; keep species, age, temperature and water the same and use many seedlings to calculate a mean [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
