insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('47835aa3-cc59-512f-a00a-846d835cf660', 'Efflux carriers are positioned on the same side of each cell [1]; auxin is actively pumped out on that side and diffuses into the next cell, so it is transported from cell to cell and concentrated in one region [1].', 'Efflux carriers are positioned on the same side of each cell [1]; auxin is actively pumped out on that side and diffuses into the next cell, so it is transported from cell to cell and concentrated in one region [1].', '[{"text": "Marking point 1", "any": ["one side", "same side"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["active", "pump", "cell to cell", "concentrated"], "all": [], "marks": 1}]'::jsonb, 'Efflux carriers are positioned on the same side of each cell [1]; auxin is actively pumped out on that side and diffuses into the next cell, so it is transported from cell to cell and concentrated in one region [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
