insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a92b43bc-e9a2-563d-9114-505b4330cb12', 'short', 'Explain how activated B-lymphocytes produce enough antibody to fight an infection.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a92b43bc-e9a2-563d-9114-505b4330cb12', 'Only a few B-cells match each antigen, so activated B-cells divide by mitosis [1]; forming a clone of plasma cells [1]; which all secrete the same specific antibody in large amounts [1].', 'Only a few B-cells match each antigen, so activated B-cells divide by mitosis [1]; forming a clone of plasma cells [1]; which all secrete the same specific antibody in large amounts [1].', '[{"text": "Marking point 1", "any": ["mitosis", "divide", "multiply"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["clone", "plasma"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["same antibody", "specific", "large amounts", "secrete"], "all": [], "marks": 1}]'::jsonb, 'Only a few B-cells match each antigen, so activated B-cells divide by mitosis [1]; forming a clone of plasma cells [1]; which all secrete the same specific antibody in large amounts [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
