insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1b5b4975-4712-5d3e-87e5-ea4d593fb9b6', 'The vaccine contains mRNA coding for a pathogen antigen [1]; body cells translate it and make the antigen protein, which triggers an immune response [1]; memory cells are produced, giving immunity without the disease [1].', 'The vaccine contains mRNA coding for a pathogen antigen [1]; body cells translate it and make the antigen protein, which triggers an immune response [1]; memory cells are produced, giving immunity without the disease [1].', '[{"text": "Marking point 1", "any": ["mrna", "codes for", "antigen"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["cells make", "translated", "protein"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["memory"], "all": [], "marks": 1}]'::jsonb, 'The vaccine contains mRNA coding for a pathogen antigen [1]; body cells translate it and make the antigen protein, which triggers an immune response [1]; memory cells are produced, giving immunity without the disease [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
